"use client";

import { AnimatePresence, motion } from "motion/react";
import { controlStyles, fieldMessageMotion } from "@/components/ui/kalos-styles";

const ease: [number, number, number, number] = [...fieldMessageMotion.ease];

export function KalosFieldMessage({ id, error, hint }: { id: string; error?: string; hint?: string }) {
  const message = error || hint;
  return (
    <AnimatePresence initial={false}>
      {message ? (
        <motion.div
          key="message"
          initial={{ height: 0, opacity: 0, marginTop: -fieldMessageMotion.gap }}
          animate={{ height: "auto", opacity: 1, marginTop: 0 }}
          exit={{ height: 0, opacity: 0, marginTop: -fieldMessageMotion.gap }}
          transition={{ duration: fieldMessageMotion.duration, ease }}
          className="overflow-hidden"
        >
          <motion.div
            key={message}
            id={id}
            role={error ? "alert" : undefined}
            initial={{ opacity: 0, y: -fieldMessageMotion.offset }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: fieldMessageMotion.textDuration, ease }}
            className={error ? controlStyles.formError : controlStyles.formStatus}
          >
            {message}
          </motion.div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

export type KalosDateRange = { start: Date; end: Date };
export const validDate = (value: unknown): value is Date => value instanceof Date && Number.isFinite(value.getTime());
export function localDay(value: Date) { const day = new Date(value); day.setHours(0, 0, 0, 0); return day; }
export function addDays(value: Date, amount: number) { const day = localDay(value); day.setDate(day.getDate() + amount); return day; }
export function monthStart(value: Date) { const day = localDay(value); day.setDate(1); return day; }
export function addMonths(value: Date, amount: number) {
  const day = monthStart(value); day.setMonth(day.getMonth() + amount);
  const last = new Date(day); last.setMonth(last.getMonth() + 1); last.setDate(0);
  day.setDate(Math.min(value.getDate(), last.getDate())); return day;
}
export function dateKey(value: Date) { return `${String(value.getFullYear()).padStart(4, "0")}-${String(value.getMonth() + 1).padStart(2, "0")}-${String(value.getDate()).padStart(2, "0")}`; }
export const sameDay = (a?: Date | null, b?: Date | null) => !!a && !!b && dateKey(a) === dateKey(b);
export const sameMonth = (a: Date, b: Date) => a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth();
export function dayCount(range: KalosDateRange) { return Math.round((Date.UTC(range.end.getFullYear(), range.end.getMonth(), range.end.getDate()) - Date.UTC(range.start.getFullYear(), range.start.getMonth(), range.start.getDate())) / 86400000) + 1; }
export function orderedRange(a: Date, b: Date): KalosDateRange { return a <= b ? { start: localDay(a), end: localDay(b) } : { start: localDay(b), end: localDay(a) }; }
export function calendarDays(month: Date, weekStartsOn = 1) { const first = monthStart(month); const start = addDays(first, -((first.getDay() - weekStartsOn + 7) % 7)); return Array.from({ length: 42 }, (_, index) => addDays(start, index)); }
export function dateFormatter(locale = "zh-CN", options: Intl.DateTimeFormatOptions = {}) {
  try { return new Intl.DateTimeFormat(locale, { calendar: "gregory", ...options }); }
  catch { return new Intl.DateTimeFormat("zh-CN", { calendar: "gregory", ...options }); }
}
export function formatRange(range: KalosDateRange, locale = "zh-CN") { const format = dateFormatter(locale, { year: "numeric", month: "short", day: "numeric" }); return `${format.format(range.start)} – ${format.format(range.end)}`; }
export function clampDay(value: Date, min?: Date, max?: Date) { return min && value < localDay(min) ? localDay(min) : max && value > localDay(max) ? localDay(max) : localDay(value); }
export const datePresets = [
  { id: "today", label: "今天", range: (today: Date) => ({ start: today, end: today }) },
  { id: "yesterday", label: "昨天", range: (today: Date) => ({ start: addDays(today, -1), end: addDays(today, -1) }) },
  ...[7, 30, 90].map(days => ({ id: `last-${days}`, label: `最近 ${days} 天`, range: (today: Date) => ({ start: addDays(today, 1 - days), end: today }) })),
  { id: "month", label: "本月", range: (today: Date) => ({ start: monthStart(today), end: today }) },
  { id: "last-month", label: "上月", range: (today: Date) => ({ start: addMonths(monthStart(today), -1), end: addDays(monthStart(today), -1) }) },
  { id: "quarter", label: "本季度", range: (today: Date) => ({ start: addMonths(monthStart(today), -(today.getMonth() % 3)), end: today }) },
  { id: "year", label: "今年至今", range: (today: Date) => { const start = monthStart(today); start.setMonth(0); return { start, end: today }; } },
];

export function parseTime(value?: string | null): number | null {
  if (!value?.trim()) return null;
  const text = value.trim().toLowerCase().replace(/[０-９]/g, digit => String(digit.charCodeAt(0) - 65296)).replace(/\s+/g, "");
  const pm = /(?:pm|下午|晚上)/.test(text), am = /(?:am|上午|早上)/.test(text);
  if (pm && am) return null;
  const period = pm ? "pm" : am ? "am" : undefined;
  const clean = text.replace(/(?:am|pm|上午|下午|早上|晚上)/g, "");
  let hour: number, minute: number;
  if (/^\d{1,2}[:.]\d{1,2}$/.test(clean)) [hour, minute] = clean.split(/[:.]/).map(Number);
  else if (/^\d{1,4}$/.test(clean)) { hour = Number(clean.length <= 2 ? clean : clean.slice(0, -2)); minute = clean.length <= 2 ? 0 : Number(clean.slice(-2)); }
  else return null;
  if (minute > 59 || hour > (period ? 12 : 23) || (period && hour < 1)) return null;
  if (period) hour = hour % 12 + (period === "pm" ? 12 : 0);
  return hour * 60 + minute;
}
export function timeValue(minutes: number) { return `${String(Math.floor(minutes / 60)).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")}`; }
export function timeSlots(step = 15, min = 0, max = 1439) { const interval = Number.isFinite(step) && step >= 1 ? Math.min(1440, Math.floor(step)) : 15; return Array.from({ length: Math.floor((max - min) / interval) + 1 }, (_, index) => timeValue(min + index * interval)); }

"use client";

import { useCallback, useEffect, useRef, useState, type RefObject } from "react";

export function useSelectFocus(controlRef: RefObject<HTMLElement | null>, disabled = false) {
  const popupRef = useRef<HTMLElement | null>(null);
  const dismissedOutside = useRef(false);
  const [focused, setFocused] = useState(false);
  const onOpenChange = useCallback((open: boolean) => {
    if (open) {
      dismissedOutside.current = false;
      setFocused(true);
    }
  }, []);
  const onCloseAutoFocus = useCallback((event: Event) => {
    if (dismissedOutside.current) event.preventDefault();
  }, []);
  const finalFocus = useCallback(() => !dismissedOutside.current, []);

  useEffect(() => {
    const contains = (target: EventTarget | null) => target instanceof Node && (
      controlRef.current?.contains(target) || popupRef.current?.contains(target)
    );
    const focusIn = (event: FocusEvent) => {
      // Closing a portal can briefly leave focus on body before restoring the trigger.
      if (event.target === document.body || event.target === document.documentElement) return;
      // A native overlay may restore its trigger after an outside press.
      // Keep that restoration from reactivating the visual focus state.
      setFocused(!!contains(event.target) && !dismissedOutside.current);
    };
    const pointerDown = (event: PointerEvent) => {
      const inside = !!contains(event.target);
      dismissedOutside.current = !inside;
      setFocused(inside);
    };
    const keyDown = (event: KeyboardEvent) => {
      if (event.key === "Tab") dismissedOutside.current = false;
      if (contains(event.target)) {
        dismissedOutside.current = false;
        setFocused(true);
      }
    };
    document.addEventListener("focusin", focusIn, true);
    document.addEventListener("pointerdown", pointerDown, true);
    document.addEventListener("keydown", keyDown, true);
    return () => {
      document.removeEventListener("focusin", focusIn, true);
      document.removeEventListener("pointerdown", pointerDown, true);
      document.removeEventListener("keydown", keyDown, true);
    };
  }, [controlRef]);

  return { focused: focused && !disabled, popupRef, onOpenChange, onCloseAutoFocus, finalFocus };
}

"use client";

import { useCallback, useEffect, useRef } from "react";

export const slidingHighlightClasses = "relative isolate before:pointer-events-none before:absolute before:left-[var(--kalos-highlight-x,0px)] before:top-[var(--kalos-highlight-y,0px)] before:z-0 before:h-[var(--kalos-highlight-height,0px)] before:w-[var(--kalos-highlight-width,0px)] before:rounded-[5px] before:bg-accent before:opacity-[var(--kalos-highlight-opacity,0)] before:transition-[left,top,width,height,opacity] before:duration-200 before:ease-[cubic-bezier(.2,.8,.2,1)] before:content-[''] [&_[role=option]]:relative [&_[role=option]]:z-10 [&_[role=option]]:bg-transparent!";

/** A single background follows the library's own focused/selected item. */
export function useSlidingHighlight(selector: string, activeSelector: string, followPointer = false) {
  const cleanup = useRef<(() => void) | null>(null);
  useEffect(() => () => cleanup.current?.(), []);
  return useCallback((node: HTMLElement | null) => {
    cleanup.current?.();
    cleanup.current = null;
    if (!node) return;
    let frame = 0;
    const position = (item: HTMLElement | null) => {
      if (!item) { node.style.setProperty("--kalos-highlight-opacity", "0"); return; }
      if (!node.contains(item) || item.matches('[aria-disabled="true"], [data-disabled]')) return;
